"""Section 1 - Create Account, Section 3 - Get Account Balance."""

from __future__ import annotations

from datetime import datetime, timezone

from tests.conftest import assert_error, balance_of, create_account, credit


def test_create_account_returns_all_required_fields(client):
    response = client.post("/accounts", json={"name": "Alice Sharma"})

    assert response.status_code == 201
    body = response.json()
    assert set(body) == {"id", "name", "balance", "created_at"}
    assert body["name"] == "Alice Sharma"
    assert body["balance"] == "0.00"
    # created_at is generated by the server and is a timezone-aware ISO-8601 timestamp.
    created_at = datetime.fromisoformat(body["created_at"].replace("Z", "+00:00"))
    assert created_at.tzinfo is not None
    assert abs((datetime.now(timezone.utc) - created_at).total_seconds()) < 60


def test_account_ids_are_unique(client):
    ids = {create_account(client, f"user-{i}")["id"] for i in range(25)}
    assert len(ids) == 25


def test_name_is_required(client):
    error = assert_error(client.post("/accounts", json={}), 400, "VALIDATION_ERROR")
    assert error["details"]["fields"][0]["field"] == "body.name"


def test_blank_name_is_rejected(client):
    assert_error(client.post("/accounts", json={"name": "   "}), 400, "VALIDATION_ERROR")


def test_name_must_be_a_string(client):
    assert_error(client.post("/accounts", json={"name": 123}), 400, "VALIDATION_ERROR")


def test_name_is_trimmed(client):
    assert create_account(client, "  Bob  ")["name"] == "Bob"


def test_client_cannot_set_initial_balance(client):
    error = assert_error(client.post("/accounts", json={"name": "Rich", "balance": 1000}), 400, "VALIDATION_ERROR")
    assert error["details"]["fields"][0]["field"] == "body.balance"


def test_client_cannot_set_id_or_created_at(client):
    response = client.post("/accounts", json={"name": "X", "id": "my-id", "created_at": "2020-01-01T00:00:00Z"})
    assert_error(response, 400, "VALIDATION_ERROR")


def test_invalid_json_body(client):
    response = client.post("/accounts", content=b"{not json", headers={"Content-Type": "application/json"})
    error = assert_error(response, 400, "VALIDATION_ERROR")
    assert error["details"]["fields"][0]["field"] == "body"


def test_get_account(client):
    account = create_account(client, "Carol")
    response = client.get(f"/accounts/{account['id']}")
    assert response.status_code == 200
    assert response.json() == account


def test_get_balance_response_shape(client):
    account = create_account(client)
    response = client.get(f"/accounts/{account['id']}/balance")

    assert response.status_code == 200
    body = response.json()
    assert body["account_id"] == account["id"]
    assert body["balance"] == "0.00"


def test_get_balance_reflects_transactions(client):
    account = create_account(client)
    credit(client, account["id"], 100, "r1")
    assert balance_of(client, account["id"]) == "100.00"


def test_get_balance_unknown_account(client):
    error = assert_error(client.get("/accounts/does-not-exist/balance"), 404, "ACCOUNT_NOT_FOUND")
    assert error["details"]["account_id"] == "does-not-exist"


def test_get_unknown_account(client):
    assert_error(client.get("/accounts/nope"), 404, "ACCOUNT_NOT_FOUND")


def test_unknown_route_uses_error_envelope(client):
    assert_error(client.get("/nothing-here"), 404, "NOT_FOUND")


def test_health(client):
    response = client.get("/health")
    assert response.status_code == 200
    assert response.json()["status"] == "ok"
